package vn.covie.catalog.model;
import jakarta.persistence.*;
import java.time.Instant;
import java.util.UUID;
@Entity @Table(name="variants") public class VariantEntity { @Id private UUID id; @Column(name="catalog_item_id",nullable=false) private UUID catalogItemId; @Column(length=120) private String sku; @Column(name="variant_name",nullable=false,length=240) private String variantName; @Column(name="is_default",nullable=false) private boolean defaultVariant; @Enumerated(EnumType.STRING) @Column(name="variant_status",nullable=false,length=20) private VariantStatus variantStatus; @Column(name="sort_order",nullable=false) private int sortOrder; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; @Column(name="deleted_at") private Instant deletedAt; @Version @Column(nullable=false) private long version; protected VariantEntity(){} public static VariantEntity create(UUID id,UUID itemId,String sku,String name,boolean isDefault,int sortOrder,Instant now){VariantEntity variant=new VariantEntity();variant.id=id;variant.catalogItemId=itemId;variant.sku=sku;variant.variantName=name;variant.defaultVariant=isDefault;variant.variantStatus=VariantStatus.ACTIVE;variant.sortOrder=sortOrder;variant.createdAt=now;variant.updatedAt=now;return variant;} public static VariantEntity createDefault(UUID id,UUID itemId,String name,Instant now){return create(id,itemId,null,name,true,0,now);} public void delete(Instant now){variantStatus=VariantStatus.DELETED;deletedAt=now;updatedAt=now;} public UUID getId(){return id;} public UUID getCatalogItemId(){return catalogItemId;} public String getSku(){return sku;} public String getVariantName(){return variantName;} public boolean isDefaultVariant(){return defaultVariant;} public VariantStatus getVariantStatus(){return variantStatus;} public int getSortOrder(){return sortOrder;} public Instant getDeletedAt(){return deletedAt;} public long getVersion(){return version;} }
